        {
          mode = VOICE_MODE_SILENCE;
        }
      else if (strcmp(argv[1], "tone") == 0)
        {
          mode = VOICE_MODE_TONE;
        }
      else if (strcmp(argv[1], "restone") == 0)
        {
          mode = VOICE_MODE_RESTONE;
