                printf("voice_echo: SPK TX failed: %d\n", ret);
                voice_oled_show(&oled, "SPK ERROR", "");
              }
            else
              {
                printf("voice_echo: playback complete\n");
                voice_oled_show(&oled, "DONE", "");
              }
          }
      }
  }

  free(samples);
  return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

